// Output Buffering Mechanism
// std::ostream uses an associated std::streambuf object.

std::ostream& os = std::cout;

// Data is typically buffered in memory first
os << "Hello";

// std::endl manipulator translates to:
os << std::endl;

// Low-level equivalent:
// 1. Insert newline character
os.put('\n');
// 2. Force the buffer contents to the device
os.flush();

// Note: Use '\n' instead of std::endl if immediate
// buffer flushing is not required (better performance).
os << "No immediate flush.\n";
